// Hook to manage Stockfish engine
const useStockfish = () => {
  const stockfish = useRef(null);

  useEffect(() => {
    stockfish.current = new Worker(
      `${process.env.PUBLIC_URL}/js/stockfish-17-lite-single.js`
    );
    return () => {
      if (stockfish.current) {
        stockfish.current.terminate();
      }
    };
  }, []);

  return stockfish;
};

// Chess Game Component
const ChessGame = () => {
  const [game, setGame] = useState(new Chess());
  const [bestMove, setBestMove] = useState("");
  const [evaluation, setEvaluation] = useState("");
  const [promotionSquare, setPromotionSquare] = useState(null);
  const [promotionSource, setPromotionSource] = useState(null);
  const [showPromotionModal, setShowPromotionModal] = useState(false);
  const [pieceStyle, setPieceStyle] = useState("cburnett"); // Default style
  const stockfish = useStockfish();

  const requestStockfishMove = () => {
    if (!stockfish.current) return;

    try {
      stockfish.current.postMessage(`position fen ${game.fen()}`);
      stockfish.current.postMessage("go depth 12");

      stockfish.current.onmessage = (event) => {
        const message = event.data;
        if (message.startsWith("bestmove")) {
          const bestMove = message.split(" ")[1];
          setBestMove(bestMove);
        } else if (message.includes("info depth 12")) {
          const parts = message.split(" ");
          const scoreIndex = parts.indexOf("score") + 2;
          if (parts[scoreIndex - 1] === "cp") {
            let score = parseInt(parts[scoreIndex], 10);
            if (game.turn() === "w") score = -score;
            setEvaluation(`${(score / 100).toFixed(2)}`);
          } else if (parts[scoreIndex - 1] === "mate") {
            const mateIn = parseInt(parts[scoreIndex], 10);
            setEvaluation(`Mate in ${Math.abs(mateIn)}`);
          }
        }
      };
    } catch (error) {
      console.error("Stockfish error:", error);
    }
  };

  // Check if a move is a promotion
  const isPromotionMove = (from, to) => {
    const piece = game.get(from);
    return (
      piece?.type === "p" &&
      ((piece.color === "w" && to[1] === "8") ||
        (piece.color === "b" && to[1] === "1"))
    );
  };

  // Handle user-selected promotion piece
  const handlePromotionSelection = (piece) => {
    if (!promotionSource || !promotionSquare) return;

    const gameCopy = new Chess(game.fen());
    gameCopy.move({
      from: promotionSource,
      to: promotionSquare,
      promotion: piece,
    });

    setGame(gameCopy);
    setShowPromotionModal(false);
    setPromotionSource(null);
    setPromotionSquare(null);
    requestStockfishMove();
  };

  // Handle piece movement
  const handleMove = (source, target) => {
    if (isPromotionMove(source, target)) {
      setPromotionSource(source);
      setPromotionSquare(target);
      setShowPromotionModal(true);
      return false;
    }

    const gameCopy = new Chess(game.fen());
    if (!gameCopy.move({ from: source, to: target })) return false;

    setGame(gameCopy);
    requestStockfishMove();
    return true;
  };

  const resetGame = () => {
    setGame(new Chess());
    setBestMove("");
    setEvaluation("");
    setShowPromotionModal(false);
  };

  useEffect(() => {
    const label = document.getElementById('piece-style-label');
    if (!label) return;

    const parent = label.parentElement;

    if (parent) {
      label.style.marginBottom = '25px';
      parent.style.display = 'block';
      parent.style.paddingTop = '30px'; // Pushes the next sibling down
    }
  }, []);

  return (
    <Container>
      <Typography variant="h4">Chess Game with Stockfish</Typography>
      <Box sx={{ mb: 2, display: "flex", gap: 2 }}>
        <Button variant="contained" onClick={resetGame}>
          Reset Game
        </Button>
        <Button variant="contained" onClick={requestStockfishMove}>
          Stockfish Move
        </Button>
      </Box>

      {/* Piece Style Selection Dropdown */}
      <Box sx={{ mb: 2 }}>
        <FormControl variant="outlined" fullWidth>
          <InputLabel id="piece-style-label" htmlFor="piece-style-select">
            Piece Style
          </InputLabel>
          <Select
            labelId="piece-style-label"
            id="piece-style-select"
            name="piece-style"
            value={pieceStyle}
            onChange={(e) => setPieceStyle(e.target.value)}
            label="Piece Style"
          >
            {chessStyles.map((style) => (
              <MenuItem key={style} value={style}>
                {style}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
      </Box>

      <Chessboard
        position={game.fen()}
        onPieceDrop={handleMove}
        boardWidth={500}
        customPieces={getCustomPieces(pieceStyle)}
      />
      <Typography variant="h6">
        Best Move: {bestMove || "Calculating..."}
      </Typography>
      <ThreatMeter evaluation={evaluation} />
      {evaluation.includes("Mate") && (
        <MateInstructions mateInfo={{ evaluation }} />
      )}
      {showPromotionModal && (
        <PromotionModal onSelectPiece={handlePromotionSelection} />
      )}
    </Container>
  );
};

export default ChessGame;
