import React from "react";
import { BrowserRouter as Router, Routes, Route, Link } from "react-router-dom";
import { Button, Container, Box, Typography } from "@mui/material";
import ChessGame from "./ChessGame";
import About from "./About";
import Tutorial from "./Tutorial";
import Home from "./Home";

const Navbar = () => {
  return (
    <Box sx={{ textAlign: "center", padding: 2 }}>
      <Typography variant="h4" color="primary">Chess App</Typography>
      <Box sx={{ display: "flex", justifyContent: "center", gap: 2, padding: 2, backgroundColor: "#333" }}>
        <Link to="/">
          <Button variant="contained" color="primary">Home</Button>
        </Link>
        <Link to="/about">
          <Button variant="contained" color="secondary">About</Button>
        </Link>
        <Link to="/game">
          <Button variant="contained" color="success">Game</Button>
        </Link>
        <Link to="/tutorial">
          <Button variant="contained" color="warning">Tutorial</Button>
        </Link>
      </Box>
    </Box>
  );
};

const App = () => {
  return (
    <Router>
      <Container>
        <Navbar />
        <Routes>
          <Route path="/" element={<Home />} />
          <Route path="/about" element={<About />} />
          <Route path="/game" element={<ChessGame />} />
          <Route path="/tutorial" element={<Tutorial />} />
        </Routes>
      </Container>
    </Router>
  );
};

export default App;